import{_ as o,o as c,c as d,a4 as a}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"OpenCode 用量同步与聚合机制分析","description":"","frontmatter":{"title":"OpenCode 用量同步与聚合机制分析","date":"2026-08-01T00:00:00.000Z"},"headers":[],"relativePath":"posts/19_opencode用量同步与聚合机制分析.md","filePath":"posts/19_opencode用量同步与聚合机制分析.md"}'),s={name:"posts/19_opencode用量同步与聚合机制分析.md"};function t(l,e,i,n,r,p){return c(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="opencode-用量同步与聚合机制分析" tabindex="-1">OpenCode 用量同步与聚合机制分析 <a class="header-anchor" href="#opencode-用量同步与聚合机制分析" aria-label="Permalink to &quot;OpenCode 用量同步与聚合机制分析&quot;">​</a></h1><blockquote><p>日期：2026-08-01 环境：ccs 在盒子（192.168.31.82，系统 eMMC + U盘 /dev/sda 挂 /mnt/shared）；opencode 在电脑；电脑经 NFS 以 /mnt/box_share 访问同一盘。 核心诉求：opencode 用量必须走盒子 U盘，不落在电脑本地；同步数据不能丢。</p></blockquote><h2 id="背景架构" tabindex="-1">背景架构 <a class="header-anchor" href="#背景架构" aria-label="Permalink to &quot;背景架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>电脑 (opencode)                    盒子 (ccs / cc-switch-web)</span></span>
<span class="line"><span>  ~/.config/opencode/*         ──符号链接──►  /mnt/box_share/.opencode/**</span></span>
<span class="line"><span>  /mnt/box_share  ◄──NFS───────  /mnt/shared (U盘, 13.4G)</span></span>
<span class="line"><span>                                     /mnt/shared/.opencode/opencode.db</span></span>
<span class="line"><span>                                     /mnt/shared/.cc-switch/cc-switch.db</span></span></code></pre></div><ul><li>ccs 每次从 opencode 的 SQLite 里拉取会话明细，写入自己的 <code>proxy_request_logs</code>。</li><li>opencode.db 与 cc-switch.db 都在共享盘上，电脑不存任何一份副本。</li></ul><h2 id="按点分析" tabindex="-1">按点分析 <a class="header-anchor" href="#按点分析" aria-label="Permalink to &quot;按点分析&quot;">​</a></h2><h3 id="_1-一键手动同步按钮已上线" tabindex="-1">1. 一键手动同步按钮已上线 <a class="header-anchor" href="#_1-一键手动同步按钮已上线" aria-label="Permalink to &quot;1. 一键手动同步按钮已上线&quot;">​</a></h3><ul><li><strong>前端</strong>：<code>DataSourceBar</code>（此前从未被挂载）挂到 <code>UsageDashboard</code>；<code>SessionSyncResult</code> 新增 <code>sources: Vec&lt;SessionSyncSource&gt;</code> 返回每源明细。</li><li><strong>后端</strong>：<code>sync_all_session_usage</code>（<code>lib.rs:271</code>）编排 5 源（claude/codex/gemini/opencode/…），每源返回 imported/errors 等明细。</li><li><strong>构建部署</strong>：commit <code>6f8ed729</code>，GH Actions arm32（<code>arm32-web-build.yml</code>）构建成功，已部署盒子 <code>/opt/cc-switch-web/cc-switch-web</code>（md5 <code>e885925b…</code>，服务 active，HTTP 200）。</li><li><strong>实测</strong>：RPC 触发 opencode 同步成功，544 imported，0 errors，5 源明细正常返回。</li></ul><h3 id="_2-opencode-配置对接已修复" tabindex="-1">2. opencode 配置对接已修复 <a class="header-anchor" href="#_2-opencode-配置对接已修复" aria-label="Permalink to &quot;2. opencode 配置对接已修复&quot;">​</a></h3><ul><li>补 1 个符号链接：<code>~/.config/opencode/opencode.json -&gt; /mnt/box_share/.opencode/opencode-config/opencode.json</code>。</li><li>验证：<code>opencode models</code> 列出 <code>sensenova/deepseek-v4-flash</code>。</li><li>ccs 写 <code>opencode-config/opencode.json</code>（含 sensenova provider）；盒子 settings <code>/root/.cc-switch/settings.json</code> 里 <code>opencodeConfigDir=/mnt/shared/.opencode/opencode-config</code>。</li><li>opencode 读配置顺序（v1.18.6 源码 <code>config.ts:258-260</code>）：config.json → opencode.json → opencode.jsonc 顺序 merge；<code>Global.Path.config</code> 默认 <code>~/.config/opencode</code>。</li></ul><h3 id="_3-api-凭证已清空" tabindex="-1">3. API 凭证已清空 <a class="header-anchor" href="#_3-api-凭证已清空" aria-label="Permalink to &quot;3. API 凭证已清空&quot;">​</a></h3><ul><li><code>/mnt/box_share/.opencode/opencode-config/auth.json</code> 原含 4 个 key（xiaomi-token-plan-cn, opencode, auto, cpa），已按用户要求全部删除，当前为 <code>{}</code>，备份已删。</li><li><code>~/.local/state/opencode/model.json</code> 中 xiaomiplan 的 recent/variant 记录已清除，备份已删。</li></ul><h3 id="_4-自动同步机制查证-盒子没有自动同步" tabindex="-1">4. 自动同步机制查证：盒子没有自动同步 <a class="header-anchor" href="#_4-自动同步机制查证-盒子没有自动同步" aria-label="Permalink to &quot;4. 自动同步机制查证：盒子没有自动同步&quot;">​</a></h3><ul><li><code>lib.rs:1759-1818</code> 存在 <code>SESSION_SYNC_INTERVAL_SECS: u64 = 60</code>：启动同步一次 + 每 60 秒循环（claude/codex/gemini/opencode）。</li><li><strong>但整个 <code>run()</code> 是 <code>#[cfg(feature=&quot;desktop&quot;)]</code></strong>（<code>lib.rs:895-897</code>），headless 盒子完全不编译 → <strong>盒子没有自动同步，只能手动点按钮</strong>。</li></ul><h3 id="_5-日志按天聚合机制-存在-但盒子只在启动时触发" tabindex="-1">5. 日志按天聚合机制：存在，但盒子只在启动时触发 <a class="header-anchor" href="#_5-日志按天聚合机制-存在-但盒子只在启动时触发" aria-label="Permalink to &quot;5. 日志按天聚合机制：存在，但盒子只在启动时触发&quot;">​</a></h3><ul><li><strong>机制</strong>：<code>src-tauri/src/database/dao/usage_rollup.rs</code> 的 <code>rollup_and_prune(retain_days=30)</code>： <ul><li>按天（对齐本地午夜）把 &gt;30 天的 <code>proxy_request_logs</code> 明细聚合进 <code>usage_daily_rollups</code>，再删除明细。</li><li>聚合维度：(日期, app_type, provider_id, model, request_model, pricing_model)，保留 token/成本/延迟加权平均。</li><li>聚合前先 <code>backfill_missing_usage_costs</code> 尽力回填计价，失败仅告警不阻断（防 0 成本永久入账）。</li><li>用 SAVEPOINT 保证原子性；删除后 <code>notify_log_recorded()</code> 通知前端重拉。</li></ul></li><li><strong>触发点对比</strong>：</li></ul><table tabindex="0"><thead><tr><th>触发点</th><th>位置</th><th>电脑 desktop</th><th>盒子 headless</th></tr></thead><tbody><tr><td>进程启动时</td><td><code>database/mod.rs:177</code>（<code>Database::init</code>）</td><td>✅</td><td>✅ <strong>有</strong></td></tr><tr><td>每 24h 定时</td><td><code>backup.rs:280</code> ← <code>lib.rs:1753</code>（desktop-only <code>run()</code> 内）</td><td>✅</td><td>❌ <strong>没有</strong></td></tr></tbody></table><ul><li>盒子走 <code>crates/server/main.rs</code> → <code>ServerState::new</code> → <code>CoreContext::new</code>（crates/core）→ <code>Database::init()</code>，所以<strong>启动时执行一次 <code>rollup_and_prune(30)</code></strong>。</li><li>24h 定时器在 desktop-only <code>run()</code> 里，web/headless 二进制不编译。盒子 <code>main.rs:146</code> 只有 1 小时的 HTTP session cleanup，与用量日志无关。</li><li><strong>含义</strong>：盒子长期不重启则 &gt;30 天明细一直堆积（U盘占用增长）；一旦重启会自动聚合 + 清理。聚合按天进 rollup 表，总量/成本/每日趋势不丢，丢的只是 &gt;30 天单条明细级审计能力。</li><li><strong>对同步数据</strong>：opencode 明细以 <code>data_source=&#39;opencode_session&#39;</code> 写入 <code>proxy_request_logs</code>，rollup 的 DELETE 一并清理（除非有 proxy 重复行经 <code>effective_usage_log_filter</code> 判定不进聚合）。</li></ul><h3 id="_6-数据量对比-20356-vs-32754" tabindex="-1">6. 数据量对比（20356 vs 32754） <a class="header-anchor" href="#_6-数据量对比-20356-vs-32754" aria-label="Permalink to &quot;6. 数据量对比（20356 vs 32754）&quot;">​</a></h3><ul><li>opencode.db <code>message</code> 表 20356 条 vs cc 库 <code>opencode_session</code> 记录 32754 条。</li><li>cc 库数据自 7/3 起连续，每日几百到几千条（最近 8/1 为 2659 条）。</li><li>request_id 均标准 3 段 <code>opencode_session:ses_*:msg_*</code>，2 段格式 0 条。</li><li><strong>差异解释</strong>：opencode.db 本地 message 表被 opencode 自身清理过；cc 库保留全量历史，非同步重复。</li></ul><h3 id="_7-关于-绝对不漏-的结论" tabindex="-1">7. 关于&quot;绝对不漏&quot;的结论 <a class="header-anchor" href="#_7-关于-绝对不漏-的结论" aria-label="Permalink to &quot;7. 关于&quot;绝对不漏&quot;的结论&quot;">​</a></h3><ul><li>无法保证绝对不漏：immutable 降级读主库会跳过 <code>-wal</code> 未 checkpoint 的尾部帧，靠下一轮 mtime 更新补齐，非永久丢失。</li><li>用户态度：接受&quot;现在 OK 很好了&quot;，不再追求绝对不漏。</li></ul><h3 id="_8-盒子缓存清理" tabindex="-1">8. 盒子缓存清理 <a class="header-anchor" href="#_8-盒子缓存清理" aria-label="Permalink to &quot;8. 盒子缓存清理&quot;">​</a></h3><ul><li><code>/tmp</code> tmpfs 从 100% 满 → 0 空。</li><li>删除旧二进制副本、测试 DB（t.db 423M 等）、40+ 调试脚本。</li><li><code>/opt/cc-switch-web/</code> 仅剩当前运行二进制；3 个 <code>.bak.*</code> 旧备份已删。</li></ul><h3 id="_9-wal-test-工具问题记录" tabindex="-1">9. wal_test 工具问题记录 <a class="header-anchor" href="#_9-wal-test-工具问题记录" aria-label="Permalink to &quot;9. wal_test 工具问题记录&quot;">​</a></h3><ul><li>最近一次改动用 <code>Row::column_count</code> 编译失败（E0599）。</li><li>后续改用 python3 sqlite3 以 immutable 模式打开共享盘 DB 成功（电脑端可用；盒子无 sqlite3）。</li></ul><h2 id="关键路径速查" tabindex="-1">关键路径速查 <a class="header-anchor" href="#关键路径速查" aria-label="Permalink to &quot;关键路径速查&quot;">​</a></h2><ul><li>web 分支代码：<code>/tmp/opencode/ccsp/repo</code>（HEAD 6f8ed729）</li><li>共享盘（电脑 /mnt/box_share = 盒子 /mnt/shared）： <ul><li><code>/mnt/shared/.opencode/opencode-config/opencode.json</code>（ccs 写，sensenova provider）</li><li><code>/mnt/shared/.opencode/opencode-config/auth.json</code>（已清空为 <code>{}</code>）</li><li><code>/mnt/shared/.opencode/opencode-db/opencode.db</code>（opencode 数据库）</li><li><code>/mnt/shared/.cc-switch/cc-switch.db</code>（ccs 数据库）</li></ul></li><li>盒子：服务 <code>cc-switch-web.service</code>（systemd，<code>OPENCODE_DB=/mnt/shared/.opencode/opencode-db/opencode.db</code>），配置 <code>/root/.cc-switch/settings.json</code></li><li>电脑端符号链接体系：<code>~/.config/opencode/*</code> 与 <code>~/.local/share/opencode/*</code> → <code>/mnt/box_share/.opencode/**</code></li><li>关键源码： <ul><li><code>src-tauri/src/lib.rs:1759-1818</code>：desktop-only 60s 自动同步循环</li><li><code>src-tauri/src/database/dao/usage_rollup.rs</code>：<code>rollup_and_prune</code> 按天聚合</li><li><code>src-tauri/src/database/backup.rs:280</code>：24h 周期 rollup（desktop-only）</li><li><code>src-tauri/src/database/mod.rs:177</code>：启动时 rollup（所有分支）</li><li><code>src-tauri/src/services/session_usage_opencode.rs</code>：WAL immutable 降级 + 同步</li><li><code>crates/server/main.rs</code>：盒子 web 入口（无自动同步/无 24h 定时）</li></ul></li></ul><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li>一键同步：可用（手动）。</li><li>自动同步：盒子无（desktop-only）。</li><li>按天聚合：盒子仅启动时执行；长期不重启 DB 会增长。</li><li>凭证：已全部清空。</li><li>数据：cc 库保留全量 opencode 明细（7/3 起连续）。</li></ul>`,30)])])}const _=o(s,[["render",t]]);export{u as __pageData,_ as default};
